package com.queryx.database.entities;
import jakarta.persistence.*; import java.time.OffsetDateTime; import java.util.UUID;
@Entity @Table(name="shipments") public class Shipment { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @Column(name="tracking_number",nullable=false,unique=true,length=100) private String trackingNumber; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="order_id",nullable=false) private Order order; @Column(nullable=false,length=30) private String status; @Column(name="shipped_at") private OffsetDateTime shippedAt; @Column(name="delivered_at") private OffsetDateTime deliveredAt; @Column(name="created_at",nullable=false) private OffsetDateTime createdAt; public UUID getId(){return id;} public String getTrackingNumber(){return trackingNumber;} public void setTrackingNumber(String v){trackingNumber=v;} public Order getOrder(){return order;} public void setOrder(Order v){order=v;} }
